{%- if page.metafields.custom.gift_mode.value -%}<style>#hxWaRoot,#hxWaWidget,#hxWaBtn,#hxWaBadge,.hx-wa-widget,.hx-wa-btn{display:none !important;}</style><script>(function(){
try{ {%- if page.metafields.custom.gift_code != blank -%}var c={{ page.metafields.custom.gift_code.value | json }};var k='giftapplied_'+c;if(!sessionStorage.getItem(k)){sessionStorage.setItem(k,'1');fetch('/discount/'+encodeURIComponent(c),{mode:'no-cors',credentials:'same-origin'});}{%- endif -%} }catch(e){}
function killWa(){['hxWaRoot','hxWaWidget','hxWaBtn','hxWaBadge'].forEach(function(id){var el=document.getElementById(id);if(el)el.remove();});[].slice.call(document.querySelectorAll('.hx-wa-widget,.hx-wa-btn')).forEach(function(el){el.remove();});}
killWa();[300,800,1500,3000].forEach(function(ms){setTimeout(killWa,ms);});
if(window.MutationObserver){var _mo=new MutationObserver(function(){killWa();});_mo.observe(document.documentElement,{childList:true,subtree:true});setTimeout(function(){_mo.disconnect();},6000);}
var CHECK='<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M4 10.5l4 4 8-9"/></svg>';
function slots(){return [].slice.call(document.querySelectorAll('.lpcart'));}
function sec(el){return el.closest('[id^="shopify-section-"]');}
function nativeBtn(slot){var s=sec(slot);return s?s.querySelector('[id^="ProductSubmitButton-"]'):null;}
function pidOf(el){return String(el.getAttribute('data-pid')).replace(/[^0-9]/g,'');}
function render(cart){var S=slots();if(!S.length)return;var ids=S.map(pidOf);var nameByPid={};S.forEach(function(x){nameByPid[pidOf(x)]=x.getAttribute('data-name');});var inCart={};(cart.items||[]).forEach(function(l){var p=String(l.product_id);if(ids.indexOf(p)>-1)inCart[p]=(inCart[p]||0)+l.quantity;});var any=false;for(var kk in inCart){any=true;break;}
var freePid=null;(cart.items||[]).some(function(l){var p=String(l.product_id);if(ids.indexOf(p)>-1){freePid=p;return true;}return false;});var freeName=freePid?nameByPid[freePid]:'';
S.forEach(function(slot){var pid=pidOf(slot),name=slot.getAttribute('data-name'),price=slot.getAttribute('data-price');var html;
if(inCart[pid]){html='<div class="lpcart__incart">'+CHECK+' no carrinho</div>';}
else if(any){html='<button type="button" class="lpcart__btn lpcart__btn--outline" data-act="swap">trocar brinde por '+name+'</button>'+'<button type="button" class="lpcart__btn lpcart__btn--primary" data-act="add">adicionar por '+price+'</button>';}
else{html='<button type="button" class="lpcart__btn lpcart__btn--primary" data-act="add">experimentar</button>';}
slot.innerHTML=html;wire(slot);});}
function wire(slot){[].slice.call(slot.querySelectorAll('[data-act]')).forEach(function(b){b.addEventListener('click',function(){if(b.getAttribute('data-act')==='add'){var nb=nativeBtn(slot);if(nb)nb.click();sched();}else{swap(slot);}});});}
function swap(slot){fetch('/cart.js',{headers:{Accept:'application/json'}}).then(function(r){return r.json();}).then(function(cart){var S=slots();var ids=S.map(pidOf);var free=(cart.items||[]).filter(function(l){return ids.indexOf(String(l.product_id))>-1;})[0];function addThis(){var nb=nativeBtn(slot);if(nb)nb.click();sched();}if(free){fetch('/cart/change.js',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({id:free.key,quantity:0})}).then(addThis);}else addThis();});}
function refresh(){fetch('/cart.js',{headers:{Accept:'application/json'}}).then(function(r){return r.json();}).then(render).catch(function(){});}
var t1,t2;function sched(){clearTimeout(t1);clearTimeout(t2);t1=setTimeout(refresh,700);t2=setTimeout(refresh,1800);}
function boot(){refresh();var d=document.querySelector('cart-drawer');if(d&&window.MutationObserver){new MutationObserver(refresh).observe(d,{attributes:true,attributeFilter:['class','open','style']});}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();</script>{%- endif -%}
